/* Respondent screens from the supplied Figma frames; no scenario transitions. */
window.MaxRespondent={install(api){
 const app=document.querySelector('.app'),A=window.MaxRespondentAssets,esc=t=>String(t??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const image=(section,key,cls='rs-icon',alt='')=>A[section]?.[key]?`<img class="${cls}" src="${A[section][key]}" alt="${esc(alt)}">`:'';
 const button=(label,icon,action='')=>`<button type="button" aria-label="${esc(label)}" ${action?`data-rs="${action}"`:''}>${icon}<span>${label}</span></button>`;
 const screen=document.createElement('section');screen.className='respondent-screen';screen.hidden=true;screen.setAttribute('aria-label','Экран приложения');app.append(screen);let current='',prior='',returnFocus=null;
 const back=()=>button('Назад',image('person','imgArrowLeft'),'back');
 function close(){screen.hidden=true;current='';returnFocus?.focus({preventScroll:true});}
 function goBack(){if(prior==='calls'){show('calls');prior='';}else close();}
 function show(kind){if(screen.hidden)returnFocus=document.activeElement;prior=current;current=kind;screen.classList.toggle('rs-person-profile',kind==='person');screen.classList.toggle('rs-bot-profile',kind==='bot');screen.hidden=false;screen.scrollTop=0;render();screen.querySelector('button')?.focus({preventScroll:true});}
 function nav(selected){const calls=selected==='Звонки',items=calls?[['Цифровой ID','imgIcon4',''],['Звонки','imgIcon5','calls'],['Чаты','imgIcon6','chats'],['Настройки','imgIcon7','']]:[['Сервисы','imgIcon',''],['Контакты','imgIcon1',''],['Чаты','imgIcon2','chats'],['Звонки','imgIcon3','calls'],['Настройки','imgIcon4','']];return `<nav class="rs-tabs-bottom" aria-label="Разделы приложения">${items.map(([label,key,action])=>`<button type="button" ${action?`data-rs="${action}"`:''} ${label===selected?'aria-current="page"':''}>${image(calls?'calls':'list9',key)}<span>${label}</span></button>`).join('')}</nav>`;}
 function render(){
  if(current==='calls'){
   const rows=[['Максим Макаров','Исходящий · 30 сек','16:20','imgAvatar','imgIcon','imgCall1'],['Алексей Комаров','Входящий · 4 мин','14:32','imgAvatar1','imgIcon1','imgVideoCall'],['Максим Макаров','Исходящий · 30 сек','Вчера','imgAvatar','imgIcon','imgVideoCall'],['Павел Селезнев','Пропущенный','Вчера','imgAvatar2','imgIcon2','imgVideoCall'],['Бабушка','Входящий · 4 мин','13 сент.','imgAvatar3','imgIcon3','imgCall1'],['Светлана Морская','Исходящий · 30 сек','13 сент.','imgAvatar4','imgIcon','imgCall1'],['Арина Громова','Входящий · 4 мин','12 сент.','imgAvatar5','imgIcon3','imgCall1'],['Максим Макаров','Входящий · 4 мин','12 сент.','imgAvatar','imgIcon3','imgCall1']];
   screen.innerHTML=`<header class="rs-calls-head"><h1>Звонки</h1></header><div class="rs-call-actions">${button('Позвонить контакту',image('calls','imgCall'))}${button('Создать групповой звонок',image('calls','imgLink'))}</div><div class="rs-call-tabs" role="tablist"><button role="tab" aria-selected="true" data-filter="all">Все</button><button role="tab" aria-selected="false" data-filter="missed">Пропущенные</button></div><div class="rs-call-list">${rows.map(([name,status,time,avatar,statusIcon,callIcon])=>`<div class="rs-call-row" data-missed="${status==='Пропущенный'}"><button class="rs-call-person" type="button" data-rs="person" data-person="${esc(name)}">${image('calls',avatar,'rs-call-avatar')}<span class="rs-call-copy"><strong class="${status==='Пропущенный'?'rs-danger':''}">${name}</strong><span>${image('calls',statusIcon,'rs-status-icon')}${status}</span></span></button><span class="rs-call-time">${time}</span><button type="button" class="rs-call-trailing" aria-label="${callIcon==='imgVideoCall'?'Видеозвонок':'Позвонить'}: ${name}">${image('calls',callIcon)}</button></div>`).join('')}</div>${nav('Звонки')}`;return;
  }
  const bot=current==='bot',s=api.state(),person=api.person(),name=bot?s.header.name:(screen.dataset.personName||person?.name||'Максим Макаров');
  const isMax=name==='Максим Макаров',matchesPerson=name===person?.name,avatar=bot?document.querySelector('.tb-avatar img')?.src:isMax?A.person.imgAvatar:(screen.dataset.personAvatar||(matchesPerson?person?.avatar:''));
  const buttons=bot?[['Чат','imgIconWrapper','chat'],['Начать','imgIconWrapper1',''],['Ещё','imgIconWrapper2','']]:[['Звонок','imgIcon',''],['Видео','imgIcon1',''],['Звук','imgIcon2',''],['Ещё','imgIcon3','']];
  screen.classList.toggle('rs-person-profile',!bot);screen.classList.toggle('rs-bot-profile',bot);
  screen.innerHTML=`<header class="rs-profile-top">${back()}<span>Инфо</span>${!bot?button('Редактировать',image('person','imgEdit')):'<span></span>'}</header><div class="rs-profile-content"><div class="rs-profile-identity">${avatar?`<img class="rs-profile-avatar" src="${esc(avatar)}" alt="">`:''}<h1>${esc(name)}</h1><p>${bot?'@'+esc(String(s.header.name).replace(/^@/,''))+' <span>· бот</span>':esc(isMax?'В сети':(matchesPerson?person?.status:'')||'')}</p></div><div class="rs-profile-actions">${buttons.map(([label,key,action])=>button(label,image(bot?'bot':'person',key),action)).join('')}</div>${bot?`<div class="rs-island"><span class="rs-label">Об этом боте</span><p>${esc(s.intro.card?.caption||'')}</p></div>`:isMax?`<div class="rs-island"><span class="rs-label">О себе</span><p>Manager, ex-tech</p></div><div class="rs-island"><span class="rs-label">Номер телефона</span><p>+7 999 987-65-43</p></div>`:''}<button class="rs-island rs-media" type="button">${image(bot?'bot':'person',bot?'imgLeadingIconSwap':'imgMedia')}<span><strong>Вложения</strong><small>Фото, видео, файлы и ссылки</small></span>${image(bot?'bot':'person','imgChevron','rs-chevron')}</button>${!bot&&isMax?`<h2 class="rs-section-label">ОБЩИЕ ЧАТЫ</h2><div class="rs-island rs-common">${[['Семья Морских','5 участников','imgAvatar1'],['Едем в Дивногорск','8 участников','imgAvatar2']].map(([name,count,key])=>`<button type="button">${image('person',key,'rs-common-avatar')}<span><strong>${name}</strong><small>${count}</small></span></button>`).join('')}</div>`:''}${bot?`<div class="rs-desktop-media"><div>${['Медиа','Файлы','Голосовые','Ссылки'].map(label=>`<button type="button">${label}</button>`).join('')}</div><p>Медиа пока нет</p></div>`:''}</div>`;
 }
 const list=document.querySelector('.chat-list-panel'),top=list.querySelector('.list-topbar');
 top.classList.add('rs-chat-top');top.querySelector('h1,h2,.list-title')?.setAttribute('data-rs-title','');
 const search=document.createElement('button');search.type='button';search.className='rs-list-search-trigger';search.setAttribute('aria-label','Поиск');search.innerHTML=image('listTop','imgIcon');const add=top.querySelector('.list-add');add.before(search);add.innerHTML=image('listTop','imgIcon1');
 const existingSearch=list.querySelector('.list-search-wrap');if(existingSearch)existingSearch.classList.add('rs-list-search');
 const filters=document.createElement('div');filters.className='rs-chat-filters';filters.setAttribute('role','tablist');filters.innerHTML='<button role="tab" aria-selected="true" data-chat-filter="all">Все <span>1</span></button><button role="tab" aria-selected="false" data-chat-filter="channels">Каналы <span>1</span></button><button role="tab" aria-selected="false" data-chat-filter="new">Новые <span>1</span></button>';top.after(filters);
 const chatRows=document.querySelector('.chat-list');
 chatRows.querySelectorAll('.cell:not(#cellBot):not(#cellPerson)').forEach(el=>el.remove());
 const row=(name,text,section,opts={})=>{const el=document.createElement('button');el.type='button';el.className='cell rs-design-cell'+(opts.favorite?' rs-favorite':'')+(opts.unread?' is-unread':'');if(opts.channel)el.dataset.channel='true';el.innerHTML=image(section,A[section]?.imgChooseImage1?'imgChooseImage1':'imgChooseImage','rs-design-avatar')+`<span class="rs-design-copy"><strong>${esc(name)}</strong><small class="${opts.unread?'rs-typing':''}">${esc(text)}</small></span><span class="rs-design-time">09:41</span>`;return el;};
 chatRows.insertBefore(row('Ирина Максимова','Ты кто?','favorite',{favorite:true}),chatRows.firstChild);
 for(const [name,text,section,opts]of [['Арина Громова','Печатает •••','list0',{unread:true}],['Лучше гор только горы','Александр: Привет, друзья! Вы слышали, что чужие орфографические ошибки и ночать зомичять сваи','list1',{}],['Наш UX','Канал создан','list2',{channel:true}],['Алёна Константинопольская','Сатурн — это газовый гигант, почти полностью состоящий из водорода и гелия','list3',{}],['Алёна Елисеева','Стикер','list4',{}],['Удалённый профиль','Ты кто?','list5',{}]])chatRows.append(row(name,text,section,opts));
 const bottom=document.createElement('div');bottom.className='rs-list-bottom';bottom.innerHTML=nav('Чаты');list.append(bottom);
 screen.addEventListener('click',e=>{const f=e.target.closest('[data-filter]');if(f){screen.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-selected',String(b===f)));screen.querySelectorAll('.rs-call-row').forEach(r=>r.hidden=f.dataset.filter==='missed'&&r.dataset.missed!=='true');return;}const target=e.target.closest('[data-rs]');if(!target)return;switch(target.dataset.rs){case'back':goBack();break;case'chats':close();app.classList.add('is-chat-list');break;case'calls':screen.classList.remove('rs-person-profile','rs-bot-profile');show('calls');break;case'chat':close();app.classList.remove('is-chat-list');api.openBot();break;case'start':close();app.classList.remove('is-chat-list');api.restart();break;case'person':screen.dataset.personName=target.dataset.person;screen.dataset.personAvatar=target.querySelector('img')?.src||'';show('person');break;}});
 bottom.addEventListener('click',e=>{if(e.target.closest('[data-rs="calls"]'))show('calls');});
 filters.addEventListener('click',e=>{const tab=e.target.closest('[data-chat-filter]');if(!tab)return;filters.querySelectorAll('button').forEach(b=>b.setAttribute('aria-selected',String(b===tab)));list.querySelectorAll('.cell').forEach(row=>row.hidden=tab.dataset.chatFilter!=='all'&&!row.matches(tab.dataset.chatFilter==='channels'?'[data-channel=true]':'.is-unread'));});
 document.querySelectorAll('.nav-item').forEach(b=>{if(b.textContent.trim()==='Звонки')b.addEventListener('click',()=>show('calls'));});
 for(const head of document.querySelectorAll('.tb-title,.tb-avatar')){head.tabIndex=0;head.setAttribute('role','button');head.setAttribute('aria-label','Открыть профиль');head.addEventListener('click',()=>{delete screen.dataset.personName;delete screen.dataset.personAvatar;show(document.querySelector('.cell.is-selected')?.id==='cellPerson'?'person':'bot');});head.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();head.click();}});}
 document.querySelector('.chat-scroll').addEventListener('click',e=>{if(e.target.closest('.contact-act[aria-label="Открыть контакт"]')){delete screen.dataset.personName;delete screen.dataset.personAvatar;show('person');}});
 document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!screen.hidden){e.stopPropagation();goBack();}});
 chatRows.addEventListener('click',e=>{if(e.target.closest('#cellBot,#cellPerson')&&!screen.hidden)close();});
 this.screen=screen;
}};
